VALUES ('Petra, Manacup (3 a 19), Xampions d''estiu Manacor, Final Xampions 2014-15 i 8a jornada LLISCA Molins', DATE '2015-07-26', '2014-15', TRUE, TRUE, 28, 71, 'arxiu AJUSC',
        'Importat de 2014-15/BARRUF71/9BARRUF-b71.xlsx (aparellaments). El motor reprodueix 42 dels 59 participants. Només se''n conserven els aparellaments i les victòries totals.', 71);

INSERT INTO inscripcions (campionat_id, jugador_id, victories)
SELECT c.id, n.jugador_id, i.v::numeric
FROM (VALUES ('aina garcia', 1), ('antoni riera', 20), ('andreu pasqual', 3), ('joan pascual', 15), ('monica cardona', 4), ('mateu xuri', 18), ('joana gelabert', 6), ('sebastia llodra', 9), ('lina maria riera', 14), ('pere grimalt vert', 11), ('magdalena morell', 17), ('antonia gelabert', 0), ('antonia riera', 13), ('margalida bonnin', 11), ('bel andreu', 12), ('joan llodra', 15), ('pere riera', 2), ('maribel servera', 18), ('montserrat nadal', 2), ('jorra santiago', 1), ('joana a. roig', 1), ('maria gaya', 14), ('marta vilardell', 7), ('joana maria flaquer', 0), ('xisco rossello', 0), ('llorenc carreres', 2), ('josep coll', 3), ('maria antonia mora', 1), ('ricard oliver', 2), ('margalida riera', 0), ('maria moll', 3), ('lluis de yzaguirre', 2), ('anna perales', 0), ('albert rico', 3), ('gabriel bas', 0), ('xabier larranaga', 0), ('joan montane', 1), ('albert rodriguez', 0), ('muntsa clotet', 2), ('miquel sese', 2), ('anna genis', 3), ('joan capdevila', 1), ('eric olmedo', 2), ('antonio arcas', 1), ('jordi marza', 2), ('elvira sese', 2), ('xavier albons', 2), ('antonio caballero', 0), ('salvador batlle', 2), ('pep vinyals', 1), ('isaac asensio', 1), ('m. lluisa penelas', 2), ('lluis parera', 0), ('marta rovira', 3), ('helena berlanga', 2), ('karma duch', 1), ('joan andreu', 1), ('joan barcelo', 2), ('isabel bargallo', 0)) AS i(norm, v)
JOIN noms_arxiu n ON n.nom_norm = i.norm
CROSS JOIN (SELECT id FROM campionats WHERE primera_edicio = 71) c
ON CONFLICT DO NOTHING;

