    ('xavier giol', 907, 13, 4, 0, 0, 'inact', NULL, TRUE, FALSE, NULL)
) AS v(norm, barruf, pt, vt, ptemp, vtemp, estat, darrera, cohort, deb, pos)
JOIN noms_arxiu n ON n.nom_norm = v.norm
CROSS JOIN (SELECT id FROM barruf_edicions WHERE numero = 72) e;

-- =============================================================================
-- Edició 73: Manacup 2016  (27/29 participants quadren amb el full)
-- =============================================================================
INSERT INTO campionats (nom, data, temporada_codi, computa_barruf, finalitzat, rondes_jugades, ordre, origen, notes, primera_edicio)
VALUES ('Manacup 2016', DATE '2016-08-31', '2015-16', TRUE, TRUE, 34, 73, 'arxiu AJUSC',
        'Importat de 2015-16/BARRUF73/BARRUF-b73.xlsx (aparellaments). El motor reprodueix 27 dels 29 participants. Només se''n conserven els aparellaments i les victòries totals. Sense data al full.', 73);

INSERT INTO inscripcions (campionat_id, jugador_id, victories)
SELECT c.id, n.jugador_id, i.v::numeric
FROM (VALUES ('joan pascual', 24), ('pere riera', 11), ('guillem pallicer', 18), ('monica cardona', 9), ('patri vitri', 12), ('bel andreu', 17), ('mateu xuri', 23), ('joan llodra', 21), ('montserrat nadal', 2), ('maribel servera', 21), ('sebastia llodra', 16), ('miquel morey', 9), ('aina garcia', 14), ('maria gaya', 21), ('lina maria riera', 18), ('cati sureda', 11), ('margalida bonnin', 19), ('andreu fuster', 20), ('roger cosso', 13), ('magdalena morell', 15), ('joana maria pasqual', 3), ('antoni riera', 24), ('antonia riera', 20), ('nina furgol', 2), ('andreu pasqual', 3), ('marta vilardell', 16), ('pere berga', 2), ('victoria sancho', 7), ('antoni casas', 15)) AS i(norm, v)
JOIN noms_arxiu n ON n.nom_norm = i.norm
CROSS JOIN (SELECT id FROM campionats WHERE primera_edicio = 73) c
ON CONFLICT DO NOTHING;

