INSERT INTO campionats (nom, data, temporada_codi, computa_barruf, finalitzat, rondes_jugades, ordre, origen, notes, primera_edicio)
VALUES ('Manacup 2016', DATE '2016-08-31', '2015-16', TRUE, TRUE, 24, 74, 'arxiu AJUSC',
        'Importat de 2015-16/BARRUF74/BARRUF-b74 (Resolt conflicte Maria Rosa - Marosa Cons).xlsx (aparellaments). El motor reprodueix 31 dels 32 participants. Només se''n conserven els aparellaments i les victòries totals. Sense data al full.', 74);

INSERT INTO inscripcions (campionat_id, jugador_id, victories)
SELECT c.id, n.jugador_id, i.v::numeric
FROM (VALUES ('maribel servera', 9), ('francesc vernet', 3), ('bel andreu', 4), ('cati sureda', 3), ('maria gaya', 4), ('antoni riera', 8), ('andreu pasqual', 2), ('joan llodra', 7), ('miquel morey', 5), ('joan pascual', 7), ('joana maria pasqual', 0), ('margalida bonnin', 4), ('roger cosso', 6), ('pere berga', 2), ('tomeu riera', 4), ('patri vitri', 7.5), ('toni mateu', 1), ('mateu xuri', 7), ('antoni alzamora', 5), ('antoni bauca', 4), ('victoria sancho', 4.5), ('m. m. matamalas', 5), ('albert mayans', 7), ('lina maria riera', 5), ('marta servera', 6), ('aina garcia', 8), ('roger pistola', 3), ('jorra santiago', 5), ('llorenc carreres', 7), ('lluis celia', 4), ('maria rosa cons', 2), ('sebastia llodra', 5)) AS i(norm, v)
JOIN noms_arxiu n ON n.nom_norm = i.norm
CROSS JOIN (SELECT id FROM campionats WHERE primera_edicio = 74) c
ON CONFLICT DO NOTHING;

INSERT INTO partides (campionat_id, ronda, jugador_1_id, jugador_2_id, resultat_1, punts_1, punts_2)
