INSERT INTO inscripcions (campionat_id, jugador_id, victories)
SELECT c.id, n.jugador_id, i.v::numeric
FROM (VALUES ('marc vigo', 8), ('joan agusti', 3), ('antonio arcas', 6), ('joan pascual', 5), ('miquel sese', 8), ('albert rodriguez', 5), ('valenti rossell', 7), ('xavier albons', 6), ('ernest teniente', 6), ('antoni riera', 7), ('lluis de yzaguirre', 7), ('joan r. manchado', 8), ('alex abad', 6), ('salvador batlle', 4), ('octavian mocanu', 7), ('anna genis', 7), ('salvador alsius', 6), ('felipe calvo', 5), ('xabier larranaga', 4), ('josep m. marti', 7), ('montse hergueta', 6), ('carles cassanyes', 7), ('joan montane', 3), ('rosa maria cot', 6), ('eulalia llargues', 4), ('lina maria riera', 4), ('balbina bresco', 5), ('eulalia abello', 5), ('joan capdevila', 5), ('agusti borrell', 5), ('albert rico', 4), ('joel segarra', 4), ('salvador comelles', 4), ('maribel servera', 3), ('eric olmedo', 6), ('enric borras', 5.5), ('gabriel bas', 5), ('karma duch', 1), ('joan barcelo', 3), ('aina garcia', 4), ('joan andreu', 6), ('joan llodra', 6), ('moises sole', 5.5), ('pau arranz', 3), ('mateu xuri', 5), ('helena berlanga', 4), ('lluis parera', 3), ('magda falco', 2), ('marta rovira', 6), ('muntsa clotet', 6), ('m. lluisa penelas', 5), ('carles llull', 4), ('neus torres', 3), ('adria maynes', 5), ('montserrat carbo', 4), ('joan torra', 2), ('angels castells', 1), ('juanjo edo', 3), ('maria ribes', 1), ('francesc gelabert', 2), ('llobet antonio', 0), ('jep ferret', 4), ('pep vinyals', 3), ('elvira sese', 4), ('magdalena morell', 2), ('jordi pujol', 5), ('sayaka kamikariya', 3), ('anna perales', 2)) AS i(norm, v)
JOIN noms_arxiu n ON n.nom_norm = i.norm
CROSS JOIN (SELECT id FROM campionats WHERE primera_edicio = 77) c
ON CONFLICT DO NOTHING;

