INSERT INTO campionats (nom, data, temporada_codi, computa_barruf, finalitzat, rondes_jugades, ordre, origen, notes, primera_edicio)
VALUES ('Campionat Sabadell Joan Oliver "Pere Quart" 2016', DATE '2017-08-31', '2016-17', TRUE, TRUE, 6, 78, 'arxiu AJUSC',
        'Importat de 2016-17/BARRUF78/BARRUF-b78 (actualitzant barrufs conflicte Rosa Maria Cons).xlsx (aparellaments). El motor reprodueix 35 dels 35 participants. Només se''n conserven els aparellaments i les victòries totals. Sense data al full.', 78);

