INSERT INTO campionats (nom, data, temporada_codi, computa_barruf, finalitzat, rondes_jugades, ordre, origen, notes, primera_edicio)
VALUES ('6è Obert dels PPCC (Badalona)', DATE '2016-11-19', '2016-17', TRUE, TRUE, 6, 79, 'arxiu AJUSC',
        'Importat de 2016-17/BARRUF79/BARRUF-b79.xlsx (aparellaments). El motor reprodueix 32 dels 32 participants. Només se''n conserven els aparellaments i les victòries totals.', 79);

INSERT INTO inscripcions (campionat_id, jugador_id, victories)
SELECT c.id, n.jugador_id, i.v::numeric
FROM (VALUES ('miquel sese', 6), ('m. lluisa penelas', 2), ('antonio arcas', 3), ('albert rico', 4), ('joan andreu', 4), ('montse hergueta', 5), ('lluis de yzaguirre', 4), ('octavian mocanu', 5), ('joan torra', 2), ('eulalia llargues', 3), ('karma duch', 4), ('adria maynes', 4), ('francesc gelabert', 3), ('carles cassanyes', 4), ('salvador comelles', 4), ('montse seriol', 0), ('gabriel bas', 1), ('joan pons', 3), ('joan capdevila', 2), ('eric olmedo', 4), ('elvira sese', 3), ('lluis parera', 2), ('joan montane', 3), ('rosa maria cot', 2), ('maria ribes', 2), ('merce illa', 2), ('xabier larranaga', 3), ('salvador batlle', 3), ('alex abad', 3), ('magda falco', 1), ('angels marce', 2.5), ('joan barcelo', 1.5)) AS i(norm, v)
