-- =============================================================================
-- Edició 80: II Campionat Vila de Petra 2017  (25/27 participants quadren amb el full)
-- =============================================================================
INSERT INTO campionats (nom, data, temporada_codi, computa_barruf, finalitzat, rondes_jugades, ordre, origen, notes, primera_edicio)
VALUES ('II Campionat Vila de Petra 2017', DATE '2017-01-07', '2016-17', TRUE, TRUE, 6, 80, 'arxiu AJUSC',
        'Importat de 2016-17/BARRUF80/BARRUF-b80.xlsx (aparellaments). El motor reprodueix 25 dels 27 participants. Només se''n conserven els aparellaments i les victòries totals.', 80);

INSERT INTO inscripcions (campionat_id, jugador_id, victories)
SELECT c.id, n.jugador_id, i.v::numeric
FROM (VALUES ('joan pascual', 5), ('beatriu defior', 3), ('sebastia llodra', 4), ('maria gaya', 4), ('joan llodra', 3), ('esperanca marti', 4), ('lina maria riera', 4), ('joan gelabert', 2), ('carles llull', 3), ('antoni alzamora', 1), ('gemma rado', 1), ('maria moll', 3), ('m. m. matamalas', 2), ('antonia riera', 3), ('antoni riera', 3), ('bel llull', 2), ('maria josep carrasco', 2), ('marisa cerdo', 2), ('aina garcia', 3), ('joana maria pasqual', 1), ('joan melia', 1), ('margalida bonnin', 2), ('miquel morey', 2), ('andreu pasqual', 0), ('francesc vernet', 0), ('pia ona verger', 1), ('joan riera', 0)) AS i(norm, v)
JOIN noms_arxiu n ON n.nom_norm = i.norm
CROSS JOIN (SELECT id FROM campionats WHERE primera_edicio = 80) c
ON CONFLICT DO NOTHING;

