-- =============================================================================
-- Edició 81: VI Campionat Eivissa 2016  (12/12 participants quadren amb el full)
-- =============================================================================
INSERT INTO campionats (nom, data, temporada_codi, computa_barruf, finalitzat, rondes_jugades, ordre, origen, notes, primera_edicio)
VALUES ('VI Campionat Eivissa 2016', DATE '2016-11-05', '2016-17', TRUE, TRUE, 5, 81, 'arxiu AJUSC',
        'Importat de 2016-17/BARRUF81/BARRUF-b81.xlsx (aparellaments). El motor reprodueix 12 dels 12 participants. Només se''n conserven els aparellaments i les victòries totals.', 81);

INSERT INTO inscripcions (campionat_id, jugador_id, victories)
SELECT c.id, n.jugador_id, i.v::numeric
FROM (VALUES ('pau arranz', 2), ('jordi escandell', 2), ('neus torres', 3), ('neus cardona', 1), ('manolo matoses', 3), ('cristina bassons', 5), ('maria planells', 1), ('alberto lahoz', 0), ('jaume vidal', 4), ('lluis ramon', 0), ('roser sacases', 0), ('josep arias', 1)) AS i(norm, v)
JOIN noms_arxiu n ON n.nom_norm = i.norm
CROSS JOIN (SELECT id FROM campionats WHERE primera_edicio = 81) c
ON CONFLICT DO NOTHING;

INSERT INTO partides (campionat_id, ronda, jugador_1_id, jugador_2_id, resultat_1, punts_1, punts_2)
SELECT c.id, p.ronda, n1.jugador_id, n2.jugador_id, p.resultat::numeric, p.p1::integer, p.p2::integer
FROM (VALUES
    (1, 'pau arranz', 'jordi escandell', NULL, NULL, NULL),
    (2, 'pau arranz', 'neus torres', NULL, NULL, NULL),
    (3, 'pau arranz', 'neus cardona', NULL, NULL, NULL),
    (4, 'pau arranz', 'manolo matoses', NULL, NULL, NULL),
    (5, 'pau arranz', 'cristina bassons', NULL, NULL, NULL),
    (1, 'cristina bassons', 'maria planells', NULL, NULL, NULL),
    (2, 'cristina bassons', 'alberto lahoz', NULL, NULL, NULL),
    (3, 'cristina bassons', 'neus torres', NULL, NULL, NULL),
    (4, 'cristina bassons', 'jaume vidal', NULL, NULL, NULL),
    (1, 'neus torres', 'lluis ramon', NULL, NULL, NULL),
    (4, 'neus torres', 'roser sacases', NULL, NULL, NULL),
    (5, 'neus torres', 'jaume vidal', NULL, NULL, NULL),
    (1, 'jaume vidal', 'josep arias', NULL, NULL, NULL),
    (2, 'jaume vidal', 'manolo matoses', NULL, NULL, NULL),
    (3, 'jaume vidal', 'maria planells', NULL, NULL, NULL),
    (3, 'josep arias', 'jordi escandell', NULL, NULL, NULL),
    (4, 'josep arias', 'neus cardona', NULL, NULL, NULL),
    (5, 'josep arias', 'roser sacases', NULL, NULL, NULL),
    (1, 'neus cardona', 'manolo matoses', NULL, NULL, NULL),
    (2, 'neus cardona', 'maria planells', NULL, NULL, NULL),
    (2, 'jordi escandell', 'lluis ramon', NULL, NULL, NULL),
    (3, 'manolo matoses', 'alberto lahoz', NULL, NULL, NULL)
) AS p(ronda, j1, j2, resultat, p1, p2)
JOIN noms_arxiu n1 ON n1.nom_norm = p.j1
LEFT JOIN noms_arxiu n2 ON n2.nom_norm = p.j2
CROSS JOIN (SELECT id FROM campionats WHERE primera_edicio = 81) c;

INSERT INTO barruf_variacions (campionat_id, jugador_id, barruf_abans, partides, victories, esperanca, factor_k, variacio, barruf_despres)
SELECT c.id, n.jugador_id, v.abans, v.partides, v.victories, v.esperanca, v.k, v.despres - v.abans, v.despres
FROM (VALUES
