-- =============================================================================
-- Edició 82: 5a LLISCA - jornades 3, 4 i 5  (31/31 participants quadren amb el full)
-- =============================================================================
INSERT INTO campionats (nom, data, temporada_codi, computa_barruf, finalitzat, rondes_jugades, ordre, origen, notes, primera_edicio)
VALUES ('5a LLISCA - jornades 3, 4 i 5', DATE '2016-11-05', '2016-17', TRUE, TRUE, 9, 82, 'arxiu AJUSC',
        'Importat de 2016-17/BARRUF82/BARRUF-b82.xlsx (aparellaments). El motor reprodueix 31 dels 31 participants. Només se''n conserven els aparellaments i les victòries totals.', 82);

INSERT INTO inscripcions (campionat_id, jugador_id, victories)
SELECT c.id, n.jugador_id, i.v::numeric
FROM (VALUES ('albert rico', 4), ('joan andreu', 4), ('marta rovira', 4), ('joan capdevila', 3), ('carles cassanyes', 9), ('joan barcelo', 5), ('eric olmedo', 7), ('alex abad', 4), ('miquel sese', 5), ('salvador batlle', 3), ('jordi bonet', 3), ('antonio arcas', 3), ('angels marce', 3), ('felipe calvo', 4), ('maria jose bonet', 1), ('sayaka kamikariya', 1), ('maria ribes', 2), ('elvira sese', 3), ('joan torra', 4), ('octavian mocanu', 7), ('balbina bresco', 2), ('xabier larranaga', 5), ('joan sans', 2), ('xavier albons', 1), ('joan montane', 3), ('eulalia llargues', 3), ('muntsa clotet', 2), ('francesc gelabert', 4), ('m. lluisa penelas', 4), ('karma duch', 0), ('magda falco', 0)) AS i(norm, v)
JOIN noms_arxiu n ON n.nom_norm = i.norm
CROSS JOIN (SELECT id FROM campionats WHERE primera_edicio = 82) c
ON CONFLICT DO NOTHING;

