    (8, 'marta rovira', 'octavian mocanu', NULL, NULL, NULL),
    (1, 'muntsa clotet', 'octavian mocanu', NULL, NULL, NULL),
    (3, 'octavian mocanu', 'sayaka kamikariya', NULL, NULL, NULL)
) AS p(ronda, j1, j2, resultat, p1, p2)
