INSERT INTO campionats (nom, data, temporada_codi, computa_barruf, finalitzat, rondes_jugades, ordre, origen, notes, primera_edicio)
VALUES ('8è Campionat de Badalona', DATE '2017-05-13', '2016-17', TRUE, TRUE, 6, 83, 'arxiu AJUSC',
        'Importat de 2016-17/BARRUF83/BARRUF-b83.xlsx (aparellaments). El motor reprodueix 28 dels 28 participants. Només se''n conserven els aparellaments i les victòries totals.', 83);

