SELECT c.id, n.jugador_id, i.v::numeric
FROM (VALUES ('octavian mocanu', 6), ('gabriel bas', 1), ('antonio arcas', 4), ('alex abad', 4), ('xavier albons', 5), ('carles cassanyes', 4), ('rosa maria cot', 4), ('joan sans', 1), ('joan capdevila', 4), ('jordi pujol', 3), ('joan andreu', 4), ('salvador batlle', 3), ('albert rico', 2), ('m. lluisa penelas', 2), ('joan barcelo', 3), ('joan montane', 1), ('montse hergueta', 4), ('marta rovira', 4), ('francesc gelabert', 2), ('felipe calvo', 3), ('salvador comelles', 4), ('peadar o braonain', 0), ('sayaka kamikariya', 3), ('xabier larranaga', 2), ('angels marce', 2), ('magda falco', 0), ('alfons codina', 2), ('karma duch', 1)) AS i(norm, v)
