INSERT INTO campionats (nom, data, temporada_codi, computa_barruf, finalitzat, rondes_jugades, ordre, origen, notes, primera_edicio)
VALUES ('5a LLISCA, J6 i J7', DATE '2017-05-06', '2016-17', TRUE, TRUE, 6, 84, 'arxiu AJUSC',
        'Importat de 2016-17/BARRUF84/BARRUF-b84.xlsx (aparellaments). El motor reprodueix 28 dels 28 participants. Només se''n conserven els aparellaments i les victòries totals.', 84);

