SELECT c.id, n.jugador_id, i.v::numeric
FROM (VALUES ('albert rico', 3), ('alex abad', 5), ('octavian mocanu', 1), ('maria ribes', 4), ('elvira sese', 1), ('joan torra', 2), ('xabier larranaga', 0), ('albert rodriguez', 1), ('magda falco', 0), ('marta rovira', 2), ('xavier albons', 2), ('joan barcelo', 2), ('angels marce', 1), ('salvador batlle', 3), ('carles cassanyes', 5), ('salvador comelles', 5), ('francesc gelabert', 1), ('carme puig', 0), ('felipe calvo', 0), ('josep m. marti', 2), ('montserrat carbo', 1), ('muntsa clotet', 2), ('helena troiano', 0), ('joan andreu', 3), ('miquel sese', 3), ('joan montane', 2), ('ramon josep colell', 2), ('sayaka kamikariya', 0)) AS i(norm, v)
