INSERT INTO campionats (nom, data, temporada_codi, computa_barruf, finalitzat, rondes_jugades, ordre, origen, notes, primera_edicio)
VALUES ('1a fase Manacup', DATE '2017-05-13', '2016-17', TRUE, TRUE, 22, 85, 'arxiu AJUSC',
        'Importat de 2016-17/BARRUF85/BARRUF-b85.xlsx (aparellaments). El motor reprodueix 2 dels 40 participants. Només se''n conserven els aparellaments i les victòries totals.', 85);

