INSERT INTO campionats (nom, data, temporada_codi, computa_barruf, finalitzat, rondes_jugades, ordre, origen, notes, primera_edicio)
VALUES ('1a fase Manacup', DATE '2017-05-13', '2016-17', TRUE, TRUE, 9, 86, 'arxiu AJUSC',
        'Importat de 2016-17/BARRUF86/BARRUF-b86.xlsx (aparellaments). El motor reprodueix 40 dels 40 participants. Només se''n conserven els aparellaments i les victòries totals.', 86);

