INSERT INTO campionats (nom, data, temporada_codi, computa_barruf, finalitzat, rondes_jugades, ordre, origen, notes, primera_edicio)
VALUES ('Xampions Estiu de Manacor', DATE '2017-08-31', '2016-17', TRUE, TRUE, 10, 90, 'arxiu AJUSC',
        'Importat de 2016-17/BARRUF90/BARRUF-b90.xlsx (aparellaments). El motor reprodueix 32 dels 32 participants. Només se''n conserven els aparellaments i les victòries totals. Sense data al full.', 90);

INSERT INTO inscripcions (campionat_id, jugador_id, victories)
SELECT c.id, n.jugador_id, i.v::numeric
FROM (VALUES ('aina garcia', 7), ('maribel servera', 7), ('miquel morey', 4), ('joana maria pasqual', 1), ('roger cosso', 6), ('joan pascual', 7), ('andreu pasqual', 4), ('victoria sancho', 4.5), ('m. m. matamalas', 4), ('margalida rossello', 4), ('carles diez', 1), ('antoni casas', 5), ('carles llull', 6), ('xisco truyols', 5), ('jorra santiago', 5), ('lina maria riera', 7), ('antoni riera', 5), ('maria gaya', 7), ('patri vitri', 6), ('esperanca marti', 6), ('bel llull', 3.5), ('joan gelabert', 5), ('tomeu riera', 8), ('cati sureda', 4), ('maria juan', 1), ('joana salas', 3), ('mateu xuri', 6), ('francesc vernet', 4), ('montse mozo', 6), ('joan llodra', 7), ('sebastia llodra', 5), ('maria josep carrasco', 5)) AS i(norm, v)
JOIN noms_arxiu n ON n.nom_norm = i.norm
