INSERT INTO campionats (nom, data, temporada_codi, computa_barruf, finalitzat, rondes_jugades, ordre, origen, notes, primera_edicio)
VALUES ('Campionat Cloenda Molins de Rei', DATE '2017-08-31', '2016-17', TRUE, TRUE, 3, 91, 'arxiu AJUSC',
        'Importat de 2016-17/BARRUF91/BARRUF-b91.xlsx (aparellaments). El motor reprodueix 11 dels 11 participants. Només se''n conserven els aparellaments i les victòries totals. Sense data al full.', 91);

INSERT INTO inscripcions (campionat_id, jugador_id, victories)
SELECT c.id, n.jugador_id, i.v::numeric
FROM (VALUES ('dani bardes', 3), ('juanjo edo', 2), ('elba ubri', 0), ('albert rodriguez', 1), ('xavier albons', 3), ('francesc gelabert', 0), ('moises sole', 1), ('isaac asensio', 2), ('victor nebreda', 1), ('montse bargallo', 0), ('isabel bargallo', 1)) AS i(norm, v)
JOIN noms_arxiu n ON n.nom_norm = i.norm
CROSS JOIN (SELECT id FROM campionats WHERE primera_edicio = 91) c
ON CONFLICT DO NOTHING;

INSERT INTO partides (campionat_id, ronda, jugador_1_id, jugador_2_id, resultat_1, punts_1, punts_2)
SELECT c.id, p.ronda, n1.jugador_id, n2.jugador_id, p.resultat::numeric, p.p1::integer, p.p2::integer
FROM (VALUES
    (1, 'dani bardes', 'juanjo edo', NULL, NULL, NULL),
    (2, 'dani bardes', 'elba ubri', NULL, NULL, NULL),
    (3, 'dani bardes', 'albert rodriguez', NULL, NULL, NULL),
    (1, 'xavier albons', 'francesc gelabert', NULL, NULL, NULL),
    (2, 'xavier albons', 'moises sole', NULL, NULL, NULL),
    (3, 'xavier albons', 'isaac asensio', NULL, NULL, NULL),
    (1, 'isaac asensio', 'victor nebreda', NULL, NULL, NULL),
    (2, 'isaac asensio', 'francesc gelabert', NULL, NULL, NULL),
    (3, 'victor nebreda', 'moises sole', NULL, NULL, NULL),
    (2, 'juanjo edo', 'montse bargallo', NULL, NULL, NULL),
    (3, 'juanjo edo', 'elba ubri', NULL, NULL, NULL),
    (1, 'moises sole', 'albert rodriguez', NULL, NULL, NULL),
    (2, 'albert rodriguez', 'isabel bargallo', NULL, NULL, NULL),
    (3, 'isabel bargallo', 'montse bargallo', NULL, NULL, NULL)
) AS p(ronda, j1, j2, resultat, p1, p2)
JOIN noms_arxiu n1 ON n1.nom_norm = p.j1
LEFT JOIN noms_arxiu n2 ON n2.nom_norm = p.j2
CROSS JOIN (SELECT id FROM campionats WHERE primera_edicio = 91) c;

INSERT INTO barruf_variacions (campionat_id, jugador_id, barruf_abans, partides, victories, esperanca, factor_k, variacio, barruf_despres)
SELECT c.id, n.jugador_id, v.abans, v.partides, v.victories, v.esperanca, v.k, v.despres - v.abans, v.despres
FROM (VALUES
    ('dani bardes', 1115.1243, 3, 3, 1.869314, 20, 1137.7381),
    ('juanjo edo', 884.6159, 3, 2, 1.026181, 30, 913.8305),
    ('elba ubri', 950, 2, 0, 0.871459, 30, 923.8562),
    ('albert rodriguez', 1218.3534, 3, 1, 2.244053, 20, 1193.4723),
    ('xavier albons', 1193.9556, 3, 3, 2.137072, 20, 1211.2142),
    ('francesc gelabert', 1032.7428, 2, 0, 0.799091, 20, 1016.761),
    ('moises sole', 1048.9517, 3, 1, 1.216348, 20, 1044.6247),
    ('isaac asensio', 1022.735, 3, 2, 1.360237, 20, 1035.5303),
    ('victor nebreda', 950, 2, 1, 0.762566, 30, 957.123),
    ('montse bargallo', 950, 2, 0, 1.176874, 30, 914.6938),
    ('isabel bargallo', 888.49, 2, 1, 0.536807, 30, 902.3858)
) AS v(norm, abans, partides, victories, esperanca, k, despres)
JOIN noms_arxiu n ON n.nom_norm = v.norm
CROSS JOIN (SELECT id FROM campionats WHERE primera_edicio = 91) c
ON CONFLICT DO NOTHING;

INSERT INTO barruf_edicions (numero, data_publicacio, temporada_codi, es_llavor, descripcio, campionats_computats, resultats_acumulats, campionats_acumulats)
SELECT 91, DATE '2017-08-31', '2016-17', FALSE, 'Arxiu: valors publicats al full de l''AJUSC.', 'Campionat Cloenda Molins de Rei', acumulats.r - 18970, acumulats.c - 99 FROM acumulats;

