-- =============================================================================
-- Edició 92: Torneig de Festa Major Manresa 2017  (18/18 participants quadren amb el full)
-- =============================================================================
INSERT INTO campionats (nom, data, temporada_codi, computa_barruf, finalitzat, rondes_jugades, ordre, origen, notes, primera_edicio)
VALUES ('Torneig de Festa Major Manresa 2017', DATE '2017-09-02', '2017-18', TRUE, TRUE, 3, 92, 'arxiu AJUSC',
        'Importat de 2017-18/BARRUF92/BARRUF-b92.xlsx (aparellaments). El motor reprodueix 18 dels 18 participants. Només se''n conserven els aparellaments i les victòries totals.', 92);

INSERT INTO inscripcions (campionat_id, jugador_id, victories)
SELECT c.id, n.jugador_id, i.v::numeric
FROM (VALUES ('joan andreu', 2), ('carles cassanyes', 3), ('m. jose antequera', 0), ('salvador batlle', 1), ('karma duch', 1), ('muntsa clotet', 2), ('felipe calvo', 1), ('salvador comelles', 2), ('eric olmedo', 2), ('xabier larranaga', 1), ('joan torra', 3), ('maria ribes', 1), ('david llussa', 1), ('marc ballus', 2), ('laia codina', 1), ('ramon josep colell', 0), ('pep torras', 2), ('sayaka kamikariya', 2)) AS i(norm, v)
JOIN noms_arxiu n ON n.nom_norm = i.norm
CROSS JOIN (SELECT id FROM campionats WHERE primera_edicio = 92) c
ON CONFLICT DO NOTHING;

