INSERT INTO campionats (nom, data, temporada_codi, computa_barruf, finalitzat, rondes_jugades, ordre, origen, notes, primera_edicio)
VALUES ('VI Campionat de Scrabble de Sabadell 2017', DATE '2017-09-02', '2017-18', TRUE, TRUE, 6, 93, 'arxiu AJUSC',
        'Importat de 2017-18/BARRUF93/BARRUF-b93.xlsx (aparellaments). El motor reprodueix 34 dels 34 participants. Només se''n conserven els aparellaments i les victòries totals.', 93);

