INSERT INTO campionats (nom, data, temporada_codi, computa_barruf, finalitzat, rondes_jugades, ordre, origen, notes, primera_edicio)
VALUES ('9è Campionat Badalona', DATE '2018-06-02', '2017-18', TRUE, TRUE, 6, 98, 'arxiu AJUSC',
        'Importat de 2017-18/BARRUF98/BARRUF-b98.xlsx (aparellaments). El motor reprodueix 43 dels 43 participants. Només se''n conserven els aparellaments i les victòries totals.', 98);

