INSERT INTO campionats (nom, data, temporada_codi, computa_barruf, finalitzat, rondes_jugades, ordre, origen, notes, primera_edicio)
VALUES ('Rondes 1 a 13 Manacup', DATE '2018-08-31', '2017-18', TRUE, TRUE, 13, 100, 'arxiu AJUSC',
        'Importat de 2017-18/BARRUF100/BARRUF-b100.xlsx (aparellaments). El motor reprodueix 48 dels 48 participants. Només se''n conserven els aparellaments i les victòries totals. Sense data al full.', 100);

INSERT INTO inscripcions (campionat_id, jugador_id, victories)
