INSERT INTO campionats (nom, data, temporada_codi, computa_barruf, finalitzat, rondes_jugades, ordre, origen, notes, primera_edicio)
VALUES ('Xampions d''Estiu 2018', DATE '2019-08-31', '2018-19', TRUE, TRUE, 12, 107, 'arxiu AJUSC',
        'Importat de 2018-19/BARRUF107/BARRUF-b107.xlsx (aparellaments). El motor reprodueix 50 dels 50 participants. Només se''n conserven els aparellaments i les victòries totals. Sense data al full.', 107);

