-- =============================================================================
-- Edició 112: Jornades LLISCA 3 i 4  (23/23 participants quadren amb el full)
-- =============================================================================
INSERT INTO campionats (nom, data, temporada_codi, computa_barruf, finalitzat, rondes_jugades, ordre, origen, notes, primera_edicio)
VALUES ('Jornades LLISCA 3 i 4', DATE '2019-08-31', '2018-19', TRUE, TRUE, 6, 112, 'arxiu AJUSC',
        'Importat de 2018-19/BARRUF112/BARRUF-b112.xlsx (aparellaments). El motor reprodueix 23 dels 23 participants. Només se''n conserven els aparellaments i les victòries totals. Sense data al full.', 112);

INSERT INTO inscripcions (campionat_id, jugador_id, victories)
SELECT c.id, n.jugador_id, i.v::numeric
FROM (VALUES ('adria maynes', 2), ('xavier albons', 3), ('salvador batlle', 3), ('marta rovira', 3), ('albert rico', 4), ('carles cassanyes', 3), ('joan sans', 1), ('joan andreu', 3), ('francesc gelabert', 3), ('balbina bresco', 2), ('diana gill', 0), ('elvira sese', 3), ('muntsa clotet', 0), ('maria ribes', 4), ('joan barcelo', 2), ('xabier larranaga', 1), ('salvador comelles', 2), ('miquel sese', 5), ('joan montane', 2), ('felipe calvo', 2), ('sayaka kamikariya', 3), ('ramon josep colell', 1), ('joan torra', 1)) AS i(norm, v)
JOIN noms_arxiu n ON n.nom_norm = i.norm
CROSS JOIN (SELECT id FROM campionats WHERE primera_edicio = 112) c
ON CONFLICT DO NOTHING;

INSERT INTO partides (campionat_id, ronda, jugador_1_id, jugador_2_id, resultat_1, punts_1, punts_2)
SELECT c.id, p.ronda, n1.jugador_id, n2.jugador_id, p.resultat::numeric, p.p1::integer, p.p2::integer
FROM (VALUES
