INSERT INTO campionats (nom, data, temporada_codi, computa_barruf, finalitzat, rondes_jugades, ordre, origen, notes, primera_edicio)
VALUES ('1a fase de la Manacup 2018/19', DATE '2019-08-31', '2018-19', TRUE, TRUE, 22, 116, 'arxiu AJUSC',
        'Importat de 2018-19/BARRUF116/BARRUF-b116.xlsx (aparellaments). El motor reprodueix 14 dels 51 participants. Només se''n conserven els aparellaments i les victòries totals. Sense data al full.', 116);

