SELECT c.id, n.jugador_id, i.v::numeric
FROM (VALUES ('aina capella', 2), ('aina garcia', 12), ('pilar sanchez', 0), ('joan pascual', 13), ('victoria sancho', 7), ('margalida bonnin', 10), ('cati sureda', 5), ('bernat amer', 4), ('joan gelabert', 8), ('antonia riera', 13), ('sebastiana mascaro', 4), ('mateu xuri', 14), ('joana maria pasqual', 5), ('pasqual sanchez', 13), ('bel andreu', 10), ('esperanca marti', 11), ('merce rojals', 4), ('aina m. vicens', 10), ('miquel morey', 8), ('antoni bauca', 10), ('carles diez', 5), ('maria gaya', 8), ('roger cosso', 11), ('miquel servera', 2), ('mateu marce', 8), ('maribel servera', 13), ('maria a. nadal', 5), ('patri vitri', 10), ('elena barcelo', 2), ('m. m. matamalas', 9), ('tomeu riera', 14), ('joana gelabert', 6), ('xisco truyols', 14), ('ana escudero', 0), ('antoni alzamora', 8), ('pere grimalt vert', 11), ('antoni riera', 15), ('jaume vives', 10), ('pau riera', 8), ('lina maria riera', 11), ('maria antonia llodra', 5), ('antoni casas', 8), ('bel llull', 10), ('guillem melis', 3), ('joana salas', 3), ('mateu mas', 2), ('joan llodra', 14), ('sebastia llodra', 11), ('francesc vernet', 4), ('miquela grimalt', 9), ('rosa barrientos', 4)) AS i(norm, v)
