INSERT INTO campionats (nom, data, temporada_codi, computa_barruf, finalitzat, rondes_jugades, ordre, origen, notes, primera_edicio)
VALUES ('Copa de Molins 2018-19', DATE '2019-08-31', '2018-19', TRUE, TRUE, 24, 118, 'arxiu AJUSC',
        'Importat de 2018-19/BARRUF118/BARRUF-b118.xlsx (aparellaments). El motor reprodueix 0 dels 9 participants. Només se''n conserven els aparellaments i les victòries totals. Sense data al full.', 118);

INSERT INTO inscripcions (campionat_id, jugador_id, victories)
SELECT c.id, n.jugador_id, i.v::numeric
FROM (VALUES ('adria maynes', 5), ('albert rodriguez', 4), ('dani bardes', 4), ('francesc gelabert', 7), ('isaac asensio', 3), ('juanjo edo', 1), ('rafel canosa', 1), ('victor nebreda', 5), ('xavier albons', 6)) AS i(norm, v)
JOIN noms_arxiu n ON n.nom_norm = i.norm
CROSS JOIN (SELECT id FROM campionats WHERE primera_edicio = 118) c
ON CONFLICT DO NOTHING;

