INSERT INTO campionats (nom, data, temporada_codi, computa_barruf, finalitzat, rondes_jugades, ordre, origen, notes, primera_edicio)
VALUES ('Cloenda CS Delta Prat', DATE '2019-07-13', '2018-19', TRUE, TRUE, 3, 119, 'arxiu AJUSC',
        'Importat de 2018-19/BARRUF119/BARRUF-b119.xlsx (aparellaments). El motor reprodueix 10 dels 10 participants. Només se''n conserven els aparellaments i les victòries totals.', 119);

INSERT INTO inscripcions (campionat_id, jugador_id, victories)
SELECT c.id, n.jugador_id, i.v::numeric
FROM (VALUES ('sayaka kamikariya', 3), ('matias camacho', 0), ('anna rodrigo', 1), ('manuel granados', 2), ('francesc gelabert', 2), ('assumpta codinach', 1), ('merce panisello', 1), ('joan puigmalet', 2), ('meritxell charavia', 0), ('cesar magaldi', 1)) AS i(norm, v)
JOIN noms_arxiu n ON n.nom_norm = i.norm
CROSS JOIN (SELECT id FROM campionats WHERE primera_edicio = 119) c
ON CONFLICT DO NOTHING;

INSERT INTO partides (campionat_id, ronda, jugador_1_id, jugador_2_id, resultat_1, punts_1, punts_2)
SELECT c.id, p.ronda, n1.jugador_id, n2.jugador_id, p.resultat::numeric, p.p1::integer, p.p2::integer
FROM (VALUES
    (1, 'sayaka kamikariya', 'matias camacho', NULL, NULL, NULL),
    (2, 'sayaka kamikariya', 'anna rodrigo', NULL, NULL, NULL),
    (3, 'sayaka kamikariya', 'manuel granados', NULL, NULL, NULL),
    (1, 'francesc gelabert', 'anna rodrigo', NULL, NULL, NULL),
    (2, 'francesc gelabert', 'matias camacho', NULL, NULL, NULL),
    (3, 'francesc gelabert', 'assumpta codinach', NULL, NULL, NULL),
    (1, 'manuel granados', 'merce panisello', NULL, NULL, NULL),
    (2, 'manuel granados', 'assumpta codinach', NULL, NULL, NULL),
    (1, 'joan puigmalet', 'assumpta codinach', NULL, NULL, NULL),
    (2, 'joan puigmalet', 'merce panisello', NULL, NULL, NULL),
    (3, 'joan puigmalet', 'meritxell charavia', NULL, NULL, NULL),
    (3, 'cesar magaldi', 'anna rodrigo', NULL, NULL, NULL),
    (3, 'merce panisello', 'matias camacho', NULL, NULL, NULL)
) AS p(ronda, j1, j2, resultat, p1, p2)
JOIN noms_arxiu n1 ON n1.nom_norm = p.j1
LEFT JOIN noms_arxiu n2 ON n2.nom_norm = p.j2
CROSS JOIN (SELECT id FROM campionats WHERE primera_edicio = 119) c;

