INSERT INTO campionats (nom, data, temporada_codi, computa_barruf, finalitzat, rondes_jugades, ordre, origen, notes, primera_edicio)
VALUES ('Cloenda MiMaM', DATE '2019-07-20', '2018-19', TRUE, TRUE, 3, 120, 'arxiu AJUSC',
        'Importat de 2018-19/BARRUF120/BARRUF-b120.xlsx (aparellaments). El motor reprodueix 15 dels 15 participants. Només se''n conserven els aparellaments i les victòries totals.', 120);

INSERT INTO inscripcions (campionat_id, jugador_id, victories)
SELECT c.id, n.jugador_id, i.v::numeric
FROM (VALUES ('dani bardes', 3), ('manel aparici', 0), ('victor nebreda', 1), ('antonio caballero', 1.5), ('albert rodriguez', 3), ('elba ubri', 0), ('isaac asensio', 2), ('marta rovira', 2), ('juanjo edo', 2), ('moises sole', 1), ('xavier albons', 2), ('adria maynes', 1.5), ('francesc gelabert', 1), ('joan sans', 1), ('josep marba', 0)) AS i(norm, v)
JOIN noms_arxiu n ON n.nom_norm = i.norm
CROSS JOIN (SELECT id FROM campionats WHERE primera_edicio = 120) c
ON CONFLICT DO NOTHING;

