INSERT INTO campionats (nom, data, temporada_codi, computa_barruf, finalitzat, rondes_jugades, ordre, origen, notes, primera_edicio)
VALUES ('Lligueta Llongueta 2018/19', DATE '2019-08-31', '2018-19', TRUE, TRUE, 15, 122, 'arxiu AJUSC',
        'Importat de 2018-19/BARRUF122/BARRUF-b122.xlsx (comprovats). El motor reprodueix 11 dels 11 participants. Sense data al full.', 122);

INSERT INTO inscripcions (campionat_id, jugador_id, victories)
SELECT c.id, n.jugador_id, i.v::numeric
FROM (VALUES ('marisa cerdo', NULL), ('aina dols', NULL), ('maria josep carrasco', NULL), ('antoni llull', NULL), ('gemma rado', NULL), ('pau gispert', NULL), ('carles llull', NULL), ('beatriu defior', NULL), ('maria moll', NULL), ('merce comas', NULL), ('maria del mar vanrell', NULL)) AS i(norm, v)
JOIN noms_arxiu n ON n.nom_norm = i.norm
CROSS JOIN (SELECT id FROM campionats WHERE primera_edicio = 122) c
ON CONFLICT DO NOTHING;

