INSERT INTO campionats (nom, data, temporada_codi, computa_barruf, finalitzat, rondes_jugades, ordre, origen, notes, primera_edicio)
VALUES ('Torneig de Festa Major de Manresa 2019', DATE '2019-09-01', '2019-20', TRUE, TRUE, 3, 125, 'arxiu AJUSC',
        'Importat de 2019-20/BARRUF125/BARRUF-b125.xlsx (comprovats). El motor reprodueix 14 dels 14 participants.', 125);

INSERT INTO inscripcions (campionat_id, jugador_id, victories)
SELECT c.id, n.jugador_id, i.v::numeric
FROM (VALUES ('merce illa', NULL), ('carles cassanyes', NULL), ('jaume serra', NULL), ('xavier albons', NULL), ('francesc gelabert', NULL), ('muntsa clotet', NULL), ('joan montane', NULL), ('joan torra', NULL), ('lluis parera', NULL), ('sayaka kamikariya', NULL), ('xabier larranaga', NULL), ('joan andreu', NULL), ('david llussa', NULL), ('maria ribes', NULL)) AS i(norm, v)
JOIN noms_arxiu n ON n.nom_norm = i.norm
CROSS JOIN (SELECT id FROM campionats WHERE primera_edicio = 125) c
ON CONFLICT DO NOTHING;

