INSERT INTO campionats (nom, data, temporada_codi, computa_barruf, finalitzat, rondes_jugades, ordre, origen, notes, primera_edicio)
VALUES ('1r Campionat Xitxarel·lo de Scrabble en Català', DATE '2020-08-31', '2019-20', TRUE, TRUE, 6, 131, 'arxiu AJUSC',
        'Importat de 2019-20/BARRUF131/BARRUF-b131.xlsx (comprovats). El motor reprodueix 12 dels 12 participants. Sense data al full.', 131);

INSERT INTO inscripcions (campionat_id, jugador_id, victories)
SELECT c.id, n.jugador_id, i.v::numeric
FROM (VALUES ('francesc gelabert', NULL), ('carles cassanyes', NULL), ('marta rovira', NULL), ('eulalia llargues', NULL), ('joaquim roe', NULL), ('salvador batlle', NULL), ('albert rico', NULL), ('joan sans', NULL), ('balbina bresco', NULL), ('marti roe', NULL), ('felipe calvo', NULL), ('cristina cabre', NULL)) AS i(norm, v)
JOIN noms_arxiu n ON n.nom_norm = i.norm
CROSS JOIN (SELECT id FROM campionats WHERE primera_edicio = 131) c
ON CONFLICT DO NOTHING;

