INSERT INTO campionats (nom, data, temporada_codi, computa_barruf, finalitzat, rondes_jugades, ordre, origen, notes, primera_edicio)
VALUES ('1a fase de la Lligueta Llongueta 2018/19', DATE '2020-08-31', '2019-20', TRUE, TRUE, 1, 133, 'arxiu AJUSC',
        'Importat de 2019-20/BARRUF133/BARRUF-b133.xlsx (comprovats). El motor reprodueix 0 dels 9 participants. Sense data al full.', 133);

INSERT INTO inscripcions (campionat_id, jugador_id, victories)
SELECT c.id, n.jugador_id, i.v::numeric
FROM (VALUES ('adria maynes', NULL), ('albert rodriguez', NULL), ('dani bardes', NULL), ('francesc gelabert', NULL), ('juanjo edo', NULL), ('moises sole', NULL), ('rafel canosa', NULL), ('victor nebreda', NULL), ('xavier albons', NULL)) AS i(norm, v)
JOIN noms_arxiu n ON n.nom_norm = i.norm
CROSS JOIN (SELECT id FROM campionats WHERE primera_edicio = 133) c
ON CONFLICT DO NOTHING;

INSERT INTO partides (campionat_id, ronda, jugador_1_id, jugador_2_id, resultat_1, punts_1, punts_2)
SELECT c.id, p.ronda, n1.jugador_id, n2.jugador_id, p.resultat::numeric, p.p1::integer, p.p2::integer
FROM (VALUES
    (1, 'adria maynes', NULL, 1, NULL, NULL),
    (1, 'albert rodriguez', NULL, 1, NULL, NULL),
    (1, 'dani bardes', NULL, 1, NULL, NULL),
    (1, 'francesc gelabert', NULL, 1, NULL, NULL),
    (1, 'juanjo edo', NULL, 1, NULL, NULL),
    (1, 'moises sole', NULL, 1, NULL, NULL),
    (1, 'rafel canosa', NULL, 1, NULL, NULL),
    (1, 'victor nebreda', NULL, 1, NULL, NULL),
    (1, 'xavier albons', NULL, 1, NULL, NULL)
) AS p(ronda, j1, j2, resultat, p1, p2)
JOIN noms_arxiu n1 ON n1.nom_norm = p.j1
LEFT JOIN noms_arxiu n2 ON n2.nom_norm = p.j2
CROSS JOIN (SELECT id FROM campionats WHERE primera_edicio = 133) c;

