INSERT INTO campionats (nom, data, temporada_codi, computa_barruf, finalitzat, rondes_jugades, ordre, origen, notes, primera_edicio)
VALUES ('1a fase de la Lligueta Llongueta 2018/19', DATE '2020-08-31', '2019-20', TRUE, TRUE, 4, 134, 'arxiu AJUSC',
        'Importat de 2019-20/BARRUF134/BARRUF-b134.xlsx (comprovats). El motor reprodueix 12 dels 12 participants. Sense data al full.', 134);

INSERT INTO inscripcions (campionat_id, jugador_id, victories)
SELECT c.id, n.jugador_id, i.v::numeric
FROM (VALUES ('antoni riera', NULL), ('francesc gelabert', NULL), ('jaume vives', NULL), ('joan pascual', NULL), ('joan llodra', NULL), ('carles llull', NULL), ('aina m. vicens', NULL), ('marta rovira', NULL), ('antonia riera', NULL), ('joan sans', NULL), ('antoni llull', NULL), ('adria maynes', NULL)) AS i(norm, v)
JOIN noms_arxiu n ON n.nom_norm = i.norm
CROSS JOIN (SELECT id FROM campionats WHERE primera_edicio = 134) c
ON CONFLICT DO NOTHING;

