INSERT INTO inscripcions (campionat_id, jugador_id, victories)
SELECT c.id, n.jugador_id, i.v::numeric
FROM (VALUES ('joan puigmalet', NULL), ('merce panisello', NULL), ('francesc gelabert', NULL), ('matias camacho', NULL), ('cesar magaldi', NULL), ('sayaka kamikariya', NULL), ('manuel granados', NULL), ('juanjo edo', NULL), ('guillem casacuberta', NULL), ('assumpta codinach', NULL)) AS i(norm, v)
