VALUES ('1a fase de la Lligueta Llongueta 2018/19', DATE '2021-08-31', '2020-21', TRUE, TRUE, 10, 137, 'arxiu AJUSC',
        'Importat de 2020-21/BARRUF137 Xàmpions Manacor/BARRUF-b137.xlsx (comprovats). El motor reprodueix 32 dels 32 participants. Sense data al full.', 137);

INSERT INTO inscripcions (campionat_id, jugador_id, victories)
SELECT c.id, n.jugador_id, i.v::numeric
FROM (VALUES ('joan llodra', NULL), ('aina garcia', NULL), ('margalida rossello', NULL), ('m. m. matamalas', NULL), ('joan gelabert', NULL), ('esperanca marti', NULL), ('cati sureda', NULL), ('roger cosso', NULL), ('maribel servera', NULL), ('tomeu riera', NULL), ('mateu mas', NULL), ('francesc vernet', NULL), ('mateu xuri', NULL), ('guillem melis', NULL), ('maria gaya', NULL), ('pere grimalt vert', NULL), ('xavi castello', NULL), ('lina maria riera', NULL), ('antoni alzamora', NULL), ('joana maria pasqual', NULL), ('francesc riera', NULL), ('xisco truyols', NULL), ('joan cabalgante', NULL), ('miquela grimalt', NULL), ('maria antonia llodra', NULL), ('antoni riera', NULL), ('sebastiana mascaro', NULL), ('carles diez', NULL), ('carles llull', NULL), ('andreu fuster', NULL), ('sebastia llodra', NULL), ('bel llull', NULL)) AS i(norm, v)
