INSERT INTO campionats (nom, data, temporada_codi, computa_barruf, finalitzat, rondes_jugades, ordre, origen, notes, primera_edicio)
VALUES ('1a fase de la Lligueta Llongueta 2018/19', DATE '2021-08-31', '2020-21', TRUE, TRUE, 5, 138, 'arxiu AJUSC',
        'Importat de 2020-21/BARRUF138 Campionat de Molins - Rafel Canosa/BARRUF-b138.xlsx (comprovats). El motor reprodueix 18 dels 18 participants. Sense data al full.', 138);

INSERT INTO inscripcions (campionat_id, jugador_id, victories)
SELECT c.id, n.jugador_id, i.v::numeric
FROM (VALUES ('pep vinyals', NULL), ('lluis de yzaguirre', NULL), ('joan sans', NULL), ('albert rodriguez', NULL), ('marta rovira', NULL), ('joaquim roe', NULL), ('juanjo edo', NULL), ('xavier albons', NULL), ('adria maynes', NULL), ('joan torra', NULL), ('jordi places', NULL), ('sayaka kamikariya', NULL), ('marti roe', NULL), ('francesc gelabert', NULL), ('xabier larranaga', NULL), ('joan montane', NULL), ('elba ubri', NULL), ('isaac asensio', NULL)) AS i(norm, v)
JOIN noms_arxiu n ON n.nom_norm = i.norm
CROSS JOIN (SELECT id FROM campionats WHERE primera_edicio = 138) c
ON CONFLICT DO NOTHING;

