INSERT INTO campionats (nom, data, temporada_codi, computa_barruf, finalitzat, rondes_jugades, ordre, origen, notes, primera_edicio)
VALUES ('1a fase de la Lligueta Llongueta 2018/19', DATE '2021-08-31', '2020-21', TRUE, TRUE, 5, 139, 'arxiu AJUSC',
        'Importat de 2020-21/BARRUF139 4a Jornada estiuenca de Scrabble a Badalona/BARRUF-b139.xlsx (comprovats). El motor reprodueix 6 dels 6 participants. Sense data al full.', 139);

INSERT INTO inscripcions (campionat_id, jugador_id, victories)
SELECT c.id, n.jugador_id, i.v::numeric
FROM (VALUES ('francesc gelabert', NULL), ('joan barcelo', NULL), ('joan sans', NULL), ('lluis de yzaguirre', NULL), ('joan torra', NULL), ('marta rovira', NULL)) AS i(norm, v)
JOIN noms_arxiu n ON n.nom_norm = i.norm
CROSS JOIN (SELECT id FROM campionats WHERE primera_edicio = 139) c
ON CONFLICT DO NOTHING;

INSERT INTO partides (campionat_id, ronda, jugador_1_id, jugador_2_id, resultat_1, punts_1, punts_2)
SELECT c.id, p.ronda, n1.jugador_id, n2.jugador_id, p.resultat::numeric, p.p1::integer, p.p2::integer
FROM (VALUES
    (1, 'francesc gelabert', 'joan barcelo', 1, 469, 395),
    (1, 'joan sans', 'lluis de yzaguirre', 0, 383, 395),
    (1, 'joan torra', 'marta rovira', 1, 442, 434),
    (2, 'lluis de yzaguirre', 'joan torra', 0, 336, 401),
    (2, 'joan barcelo', 'joan sans', 0, 376, 446),
    (2, 'francesc gelabert', 'marta rovira', 0, 306, 679),
    (3, 'joan sans', 'joan torra', 0, 289, 434),
    (3, 'francesc gelabert', 'lluis de yzaguirre', 0, 311, 484),
    (3, 'joan barcelo', 'marta rovira', 0, 329, 544),
    (4, 'joan torra', 'joan barcelo', 0, 368, 530),
    (4, 'lluis de yzaguirre', 'marta rovira', 1, 532, 279),
    (4, 'francesc gelabert', 'joan sans', 1, 479, 388),
    (5, 'joan sans', 'marta rovira', 0, 361, 470),
    (5, 'lluis de yzaguirre', 'joan barcelo', 1, 506, 363),
    (5, 'francesc gelabert', 'joan torra', 0, 338, 421)
) AS p(ronda, j1, j2, resultat, p1, p2)
JOIN noms_arxiu n1 ON n1.nom_norm = p.j1
LEFT JOIN noms_arxiu n2 ON n2.nom_norm = p.j2
CROSS JOIN (SELECT id FROM campionats WHERE primera_edicio = 139) c;

INSERT INTO barruf_variacions (campionat_id, jugador_id, barruf_abans, partides, victories, esperanca, factor_k, variacio, barruf_despres)
