INSERT INTO inscripcions (campionat_id, jugador_id, victories)
SELECT c.id, n.jugador_id, i.v::numeric
FROM (VALUES ('albert rodriguez', NULL), ('adria maynes', NULL), ('dani bardes', NULL), ('francesc gelabert', NULL), ('guillem prats', NULL), ('juanjo edo', NULL), ('xavier albons', NULL)) AS i(norm, v)
JOIN noms_arxiu n ON n.nom_norm = i.norm
CROSS JOIN (SELECT id FROM campionats WHERE primera_edicio = 145) c
ON CONFLICT DO NOTHING;

