INSERT INTO inscripcions (campionat_id, jugador_id, victories)
SELECT c.id, n.jugador_id, i.v::numeric
FROM (VALUES ('xavier albons', NULL), ('francesc gelabert', NULL), ('albert rodriguez', NULL), ('joan andreu arribas', NULL), ('dani bardes', NULL), ('antonio caballero', NULL), ('adria maynes', NULL), ('jordi places', NULL), ('marta rovira', NULL), ('joan sans', NULL)) AS i(norm, v)
JOIN noms_arxiu n ON n.nom_norm = i.norm
CROSS JOIN (SELECT id FROM campionats WHERE primera_edicio = 146) c
ON CONFLICT DO NOTHING;

INSERT INTO partides (campionat_id, ronda, jugador_1_id, jugador_2_id, resultat_1, punts_1, punts_2)
