INSERT INTO campionats (nom, data, temporada_codi, computa_barruf, finalitzat, rondes_jugades, ordre, origen, notes, primera_edicio)
VALUES ('Xàmpions Manacor 2022', DATE '2022-08-31', '2021-22', TRUE, TRUE, 10, 148, 'arxiu AJUSC',
        'Importat de 2021-22/Barruf 148 - Xàmpions 2022/BARRUF-148 2021-22.xlsx (comprovats). El motor reprodueix 32 dels 32 participants. Sense data al full.', 148);

INSERT INTO inscripcions (campionat_id, jugador_id, victories)
SELECT c.id, n.jugador_id, i.v::numeric
FROM (VALUES ('jaume rigo', NULL), ('xavi castello', NULL), ('joan pascual', NULL), ('andreu fuster', NULL), ('joan gelabert', NULL), ('francesca font', NULL), ('bel llull', NULL), ('pere grimalt vert', NULL), ('aina garcia', NULL), ('rosa barrientos', NULL), ('m. m. matamalas', NULL), ('roger cosso', NULL), ('maria antonia llodra', NULL), ('lina maria riera', NULL), ('paula girart', NULL), ('bernat amer', NULL), ('sebastiana mascaro', NULL), ('maria gaya', NULL), ('joana genovart', NULL), ('andreu pasqual', NULL), ('margalida bonnin', NULL), ('xisco truyols', NULL), ('eulalia ferriol', NULL), ('maribel servera', NULL), ('marga font', NULL), ('sebastia llodra', NULL), ('esperanca marti', NULL), ('carles diez', NULL), ('marga gelabert', NULL), ('joan llodra', NULL), ('antoni riera', NULL), ('lluis fuster amer', NULL)) AS i(norm, v)
