INSERT INTO campionats (nom, data, temporada_codi, computa_barruf, finalitzat, rondes_jugades, ordre, origen, notes, primera_edicio)
VALUES ('9è Mundial Scrabble', DATE '2022-11-20', '2022-23', TRUE, TRUE, 10, 150, 'arxiu AJUSC',
        'Importat de 2022-23/Barruf 150 - 9è Mundial/BARRUF-150 9è Mundial.xlsx (comprovats). El motor reprodueix 45 dels 45 participants.', 150);

INSERT INTO inscripcions (campionat_id, jugador_id, victories)
SELECT c.id, n.jugador_id, i.v::numeric
FROM (VALUES ('antoni riera', NULL), ('carles llull', NULL), ('lina maria riera', NULL), ('carles cassanyes', NULL), ('lluis de yzaguirre', NULL), ('joan montane', NULL), ('enric borras', NULL), ('octavian mocanu', NULL), ('aina garcia', NULL), ('eulalia abello', NULL), ('balbina bresco', NULL), ('marta rovira', NULL), ('albert rodriguez', NULL), ('daniel ramos', NULL), ('joan torra', NULL), ('maria moll', NULL), ('alex abad', NULL), ('joan sans', NULL), ('rosa maria cot', NULL), ('adria maynes', NULL), ('esperanca marti', NULL), ('francesc gelabert', NULL), ('antoni llull', NULL), ('eric olmedo', NULL), ('xavier albons', NULL), ('merce illa', NULL), ('victor nebreda', NULL), ('salvador batlle', NULL), ('salvador alsius', NULL), ('gabriel bas', NULL), ('pep vinyals', NULL), ('joan andreu', NULL), ('eulalia llargues', NULL), ('manuel granados', NULL), ('felipe calvo', NULL), ('m. lluisa penelas', NULL), ('manolo matoses', NULL), ('neus torres', NULL), ('joan barcelo', NULL), ('angels marce', NULL), ('xabier larranaga', NULL), ('antonio caballero', NULL), ('josep marba', NULL), ('sayaka kamikariya', NULL), ('isaac asensio', NULL)) AS i(norm, v)
