INSERT INTO inscripcions (campionat_id, jugador_id, victories)
SELECT c.id, n.jugador_id, i.v::numeric
FROM (VALUES ('carles cassanyes', NULL), ('angels castells', NULL), ('lluis de yzaguirre', NULL), ('armand sanmamed', NULL), ('marta rovira', NULL), ('joan sans', NULL), ('adria maynes', NULL), ('eulalia llargues', NULL), ('salvador alsius', NULL), ('david roig', NULL), ('albert rico', NULL), ('anna salgot', NULL), ('eric olmedo', NULL), ('xabier larranaga', NULL), ('joan andreu', NULL), ('joan barcelo', NULL), ('francesc gallen', NULL), ('francesc gelabert', NULL), ('jordi plana espanol', NULL), ('salvador batlle', NULL), ('jordi comasolives', NULL), ('joan torra', NULL)) AS i(norm, v)
