INSERT INTO campionats (nom, data, temporada_codi, computa_barruf, finalitzat, rondes_jugades, ordre, origen, notes, primera_edicio)
VALUES ('ManaCup 2022-23', DATE '2023-06-29', '2022-23', TRUE, TRUE, 12, 156, 'arxiu AJUSC',
        'Importat de 2022-23/Barruf 156 - ManaCup 2022-23/Barruf 156 - ManaCup 2022-23.xlsx (comprovats). El motor reprodueix 4 dels 4 participants.', 156);

INSERT INTO inscripcions (campionat_id, jugador_id, victories)
SELECT c.id, n.jugador_id, i.v::numeric
FROM (VALUES ('margalida fuster', NULL), ('nicolau vidal', NULL), ('toni clar', NULL), ('bel fullana', NULL)) AS i(norm, v)
JOIN noms_arxiu n ON n.nom_norm = i.norm
CROSS JOIN (SELECT id FROM campionats WHERE primera_edicio = 156) c
ON CONFLICT DO NOTHING;

INSERT INTO partides (campionat_id, ronda, jugador_1_id, jugador_2_id, resultat_1, punts_1, punts_2)
SELECT c.id, p.ronda, n1.jugador_id, n2.jugador_id, p.resultat::numeric, p.p1::integer, p.p2::integer
FROM (VALUES
    (1, 'margalida fuster', NULL, 1, NULL, NULL),
    (2, 'margalida fuster', NULL, 1, NULL, NULL),
    (3, 'margalida fuster', NULL, 1, NULL, NULL),
    (5, 'nicolau vidal', NULL, 1, NULL, NULL),
    (7, 'nicolau vidal', NULL, 1, NULL, NULL),
    (9, 'nicolau vidal', NULL, 1, NULL, NULL),
    (11, 'nicolau vidal', NULL, 1, NULL, NULL),
    (11, 'toni clar', 'bel fullana', 0, 186, 343),
    (12, 'nicolau vidal', NULL, 1, NULL, NULL),
    (13, 'bel fullana', NULL, 1, NULL, NULL),
    (13, 'toni clar', 'nicolau vidal', 1, 264, 248),
    (14, 'bel fullana', 'nicolau vidal', 1, 415, 221),
    (18, 'bel fullana', NULL, 1, NULL, NULL),
    (19, 'bel fullana', NULL, 1, NULL, NULL)
) AS p(ronda, j1, j2, resultat, p1, p2)
JOIN noms_arxiu n1 ON n1.nom_norm = p.j1
LEFT JOIN noms_arxiu n2 ON n2.nom_norm = p.j2
CROSS JOIN (SELECT id FROM campionats WHERE primera_edicio = 156) c;

INSERT INTO barruf_variacions (campionat_id, jugador_id, barruf_abans, partides, victories, esperanca, factor_k, variacio, barruf_despres)
SELECT c.id, n.jugador_id, v.abans, v.partides, v.victories, v.esperanca, v.k, v.despres - v.abans, v.despres
FROM (VALUES
    ('nicolau vidal', 950, 2, 0, 1.000000, 30, 920),
    ('toni clar', 950, 2, 1, 1.000000, 30, 950),
    ('bel fullana', 950, 2, 2, 1.000000, 30, 980)
) AS v(norm, abans, partides, victories, esperanca, k, despres)
JOIN noms_arxiu n ON n.nom_norm = v.norm
CROSS JOIN (SELECT id FROM campionats WHERE primera_edicio = 156) c
ON CONFLICT DO NOTHING;

INSERT INTO barruf_edicions (numero, data_publicacio, temporada_codi, es_llavor, descripcio, campionats_computats, resultats_acumulats, campionats_acumulats)
SELECT 156, DATE '2023-06-29', '2022-23', FALSE, 'Arxiu: valors publicats al full de l''AJUSC.', 'ManaCup 2022-23', acumulats.r - 6146, acumulats.c - 34 FROM acumulats;

