SELECT c.id, p.ronda, n1.jugador_id, n2.jugador_id, p.resultat::numeric, p.p1::integer, p.p2::integer
FROM (VALUES
    (1, 'marta rovira', 'francesc gelabert', 0, 384, 387),
    (1, 'joan sans', 'lluis de yzaguirre', 0, 319, 447),
    (1, 'elba ubri', 'xavier albons', 0, 347, 434),
    (1, 'josep marba', 'albert rodriguez', 0, 248, 451),
    (1, 'adria maynes', 'jordi places', 1, 489, 214),
    (2, 'lluis de yzaguirre', 'adria maynes', 1, 533, 381),
    (2, 'xavier albons', 'albert rodriguez', 0, 362, 399),
    (2, 'joan sans', 'francesc gelabert', 0, 361, 423),
    (2, 'marta rovira', 'jordi places', 1, 491, 157),
    (2, 'elba ubri', 'josep marba', 1, 366, 279),
    (3, 'albert rodriguez', 'lluis de yzaguirre', 0, 364, 484),
    (3, 'francesc gelabert', 'xavier albons', 1, 427, 406),
    (3, 'elba ubri', 'marta rovira', 0, 190, 571),
    (3, 'josep marba', 'adria maynes', 0, 239, 533),
    (3, 'joan sans', 'jordi places', 1, 388, 230)
) AS p(ronda, j1, j2, resultat, p1, p2)
JOIN noms_arxiu n1 ON n1.nom_norm = p.j1
LEFT JOIN noms_arxiu n2 ON n2.nom_norm = p.j2
CROSS JOIN (SELECT id FROM campionats WHERE primera_edicio = 158) c;

INSERT INTO barruf_variacions (campionat_id, jugador_id, barruf_abans, partides, victories, esperanca, factor_k, variacio, barruf_despres)
SELECT c.id, n.jugador_id, v.abans, v.partides, v.victories, v.esperanca, v.k, v.despres - v.abans, v.despres
