-- =============================================================================
-- Edició 160: Xàmpions Manacor 2023  (2/2 participants quadren amb el full)
-- =============================================================================
INSERT INTO campionats (nom, data, temporada_codi, computa_barruf, finalitzat, rondes_jugades, ordre, origen, notes, primera_edicio)
VALUES ('Xàmpions Manacor 2023', DATE '2023-08-31', '2022-23', TRUE, TRUE, 4, 160, 'arxiu AJUSC',
        'Importat de 2022-23/Barruf 160 - Xàmpions Manacor 2023/Barruf 160 - Xàmpions Manacor 2023.xlsx (comprovats). El motor reprodueix 2 dels 2 participants. Sense data al full.', 160);

INSERT INTO inscripcions (campionat_id, jugador_id, victories)
SELECT c.id, n.jugador_id, i.v::numeric
FROM (VALUES ('esther alcover', NULL), ('catalina vallbona', NULL)) AS i(norm, v)
JOIN noms_arxiu n ON n.nom_norm = i.norm
CROSS JOIN (SELECT id FROM campionats WHERE primera_edicio = 160) c
ON CONFLICT DO NOTHING;

INSERT INTO partides (campionat_id, ronda, jugador_1_id, jugador_2_id, resultat_1, punts_1, punts_2)
SELECT c.id, p.ronda, n1.jugador_id, n2.jugador_id, p.resultat::numeric, p.p1::integer, p.p2::integer
FROM (VALUES
    (1, 'esther alcover', NULL, 1, NULL, NULL),
    (2, 'esther alcover', NULL, 1, NULL, NULL),
    (3, 'esther alcover', NULL, 1, NULL, NULL),
    (4, 'esther alcover', NULL, 1, NULL, NULL),
    (1, 'catalina vallbona', NULL, 1, NULL, NULL),
    (2, 'catalina vallbona', NULL, 1, NULL, NULL)
) AS p(ronda, j1, j2, resultat, p1, p2)
JOIN noms_arxiu n1 ON n1.nom_norm = p.j1
LEFT JOIN noms_arxiu n2 ON n2.nom_norm = p.j2
CROSS JOIN (SELECT id FROM campionats WHERE primera_edicio = 160) c;

INSERT INTO barruf_edicions (numero, data_publicacio, temporada_codi, es_llavor, descripcio, campionats_computats, resultats_acumulats, campionats_acumulats)
SELECT 160, DATE '2023-08-31', '2022-23', FALSE, 'Arxiu: valors publicats al full de l''AJUSC.', 'Xàmpions Manacor 2023', acumulats.r - 5970, acumulats.c - 30 FROM acumulats;

INSERT INTO barruf_valors (
    edicio_id, jugador_id, barruf, partides_totals, victories_totals,
