INSERT INTO campionats (nom, data, temporada_codi, computa_barruf, finalitzat, rondes_jugades, ordre, origen, notes, primera_edicio)
VALUES ('10è Campionat de Scrabble en català de Sabadell', DATE '2023-09-30', '2023-24', TRUE, TRUE, 5, 161, 'arxiu AJUSC',
        'Importat de 2023-24/Barruf 161 - 10è Campionat de Scrabble en català de Sabadell/Barruf 161 - 10è Campionat de Scrabble en català de Sabadell.xlsx (comprovats). El motor reprodueix 2 dels 2 participants.', 161);

INSERT INTO inscripcions (campionat_id, jugador_id, victories)
SELECT c.id, n.jugador_id, i.v::numeric
FROM (VALUES ('angels torrens', NULL), ('jordi plana espanol', NULL)) AS i(norm, v)
JOIN noms_arxiu n ON n.nom_norm = i.norm
CROSS JOIN (SELECT id FROM campionats WHERE primera_edicio = 161) c
ON CONFLICT DO NOTHING;

INSERT INTO partides (campionat_id, ronda, jugador_1_id, jugador_2_id, resultat_1, punts_1, punts_2)
SELECT c.id, p.ronda, n1.jugador_id, n2.jugador_id, p.resultat::numeric, p.p1::integer, p.p2::integer
FROM (VALUES
    (1, 'angels torrens', NULL, 1, NULL, NULL),
    (2, 'angels torrens', NULL, 1, NULL, NULL),
    (3, 'angels torrens', NULL, 1, NULL, NULL),
    (5, 'jordi plana espanol', NULL, 1, NULL, NULL),
    (6, 'jordi plana espanol', NULL, 1, NULL, NULL)
) AS p(ronda, j1, j2, resultat, p1, p2)
JOIN noms_arxiu n1 ON n1.nom_norm = p.j1
LEFT JOIN noms_arxiu n2 ON n2.nom_norm = p.j2
CROSS JOIN (SELECT id FROM campionats WHERE primera_edicio = 161) c;

