INSERT INTO campionats (nom, data, temporada_codi, computa_barruf, finalitzat, rondes_jugades, ordre, origen, notes, primera_edicio)
VALUES ('2n Campionat de Scrabble de l''escarxofa del Prat', DATE '2024-01-13', '2023-24', TRUE, TRUE, 4, 162, 'arxiu AJUSC',
        'Importat de 2023-24/Barruf 162 - 2n Campionat de Scrabble de l_escarxofa del Prat/Barruf 162 - 2n Campionat de Scrabble de l_escarxofa del Prat.xlsx (comprovats). El motor reprodueix 2 dels 2 participants.', 162);

INSERT INTO inscripcions (campionat_id, jugador_id, victories)
SELECT c.id, n.jugador_id, i.v::numeric
FROM (VALUES ('jordi plana espanol', NULL), ('josep fiol', NULL)) AS i(norm, v)
JOIN noms_arxiu n ON n.nom_norm = i.norm
CROSS JOIN (SELECT id FROM campionats WHERE primera_edicio = 162) c
ON CONFLICT DO NOTHING;

INSERT INTO partides (campionat_id, ronda, jugador_1_id, jugador_2_id, resultat_1, punts_1, punts_2)
SELECT c.id, p.ronda, n1.jugador_id, n2.jugador_id, p.resultat::numeric, p.p1::integer, p.p2::integer
FROM (VALUES
    (2, 'jordi plana espanol', NULL, 1, NULL, NULL),
    (4, 'jordi plana espanol', NULL, 1, NULL, NULL),
    (4, 'josep fiol', NULL, 1, NULL, NULL),
    (5, 'jordi plana espanol', NULL, 1, NULL, NULL),
    (5, 'josep fiol', NULL, 1, NULL, NULL),
    (6, 'jordi plana espanol', NULL, 1, NULL, NULL),
    (6, 'josep fiol', NULL, 1, NULL, NULL)
) AS p(ronda, j1, j2, resultat, p1, p2)
JOIN noms_arxiu n1 ON n1.nom_norm = p.j1
LEFT JOIN noms_arxiu n2 ON n2.nom_norm = p.j2
CROSS JOIN (SELECT id FROM campionats WHERE primera_edicio = 162) c;

