-- =============================================================================
-- Edició 169: VIII Campionat de Scrabble Ciutat de Manacor  (1/1 participants quadren amb el full)
-- =============================================================================
INSERT INTO campionats (nom, data, temporada_codi, computa_barruf, finalitzat, rondes_jugades, ordre, origen, notes, primera_edicio)
VALUES ('VIII Campionat de Scrabble Ciutat de Manacor', DATE '2024-06-01', '2023-24', TRUE, TRUE, 1, 169, 'arxiu AJUSC',
        'Importat de 2023-24/Barruf 169 - VIII Campionat de Scrabble Ciutat de Manacor/Barruf 169 - VIII Campionat de Scrabble Ciutat de Manacor.xlsx (comprovats). El motor reprodueix 1 dels 1 participants.', 169);

INSERT INTO inscripcions (campionat_id, jugador_id, victories)
SELECT c.id, n.jugador_id, i.v::numeric
FROM (VALUES ('joan antoni cerrato rossello', NULL)) AS i(norm, v)
JOIN noms_arxiu n ON n.nom_norm = i.norm
CROSS JOIN (SELECT id FROM campionats WHERE primera_edicio = 169) c
ON CONFLICT DO NOTHING;

INSERT INTO partides (campionat_id, ronda, jugador_1_id, jugador_2_id, resultat_1, punts_1, punts_2)
SELECT c.id, p.ronda, n1.jugador_id, n2.jugador_id, p.resultat::numeric, p.p1::integer, p.p2::integer
FROM (VALUES
    (2, 'joan antoni cerrato rossello', NULL, 1, NULL, NULL)
) AS p(ronda, j1, j2, resultat, p1, p2)
JOIN noms_arxiu n1 ON n1.nom_norm = p.j1
LEFT JOIN noms_arxiu n2 ON n2.nom_norm = p.j2
CROSS JOIN (SELECT id FROM campionats WHERE primera_edicio = 169) c;

INSERT INTO barruf_edicions (numero, data_publicacio, temporada_codi, es_llavor, descripcio, campionats_computats, resultats_acumulats, campionats_acumulats)
SELECT 169, DATE '2024-06-01', '2023-24', FALSE, 'Arxiu: valors publicats al full de l''AJUSC.', 'VIII Campionat de Scrabble Ciutat de Manacor', acumulats.r - 4376, acumulats.c - 21 FROM acumulats;

INSERT INTO barruf_valors (
    edicio_id, jugador_id, barruf, partides_totals, victories_totals,
