-- =============================================================================
-- Edició 171: Copa de Molins 2023-24  (7/7 participants quadren amb el full)
-- =============================================================================
INSERT INTO campionats (nom, data, temporada_codi, computa_barruf, finalitzat, rondes_jugades, ordre, origen, notes, primera_edicio)
VALUES ('Copa de Molins 2023-24', DATE '2024-08-31', '2023-24', TRUE, TRUE, 7, 171, 'arxiu AJUSC',
        'Importat de 2023-24/Barruf 171 - Copa de Molins 2023-24/Barruf 171 - Copa de Molins 2023-24.xlsx (comprovats). El motor reprodueix 7 dels 7 participants. Sense data al full.', 171);

INSERT INTO inscripcions (campionat_id, jugador_id, victories)
SELECT c.id, n.jugador_id, i.v::numeric
FROM (VALUES ('albert rodriguez', NULL), ('adria maynes', NULL), ('dani bardes', NULL), ('francesc gelabert', NULL), ('joan sans', NULL), ('marta rovira', NULL), ('xavier albons', NULL)) AS i(norm, v)
JOIN noms_arxiu n ON n.nom_norm = i.norm
CROSS JOIN (SELECT id FROM campionats WHERE primera_edicio = 171) c
ON CONFLICT DO NOTHING;

INSERT INTO partides (campionat_id, ronda, jugador_1_id, jugador_2_id, resultat_1, punts_1, punts_2)
SELECT c.id, p.ronda, n1.jugador_id, n2.jugador_id, p.resultat::numeric, p.p1::integer, p.p2::integer
FROM (VALUES
    (1, 'albert rodriguez', 'adria maynes', 0, 384, 446),
    (2, 'dani bardes', 'adria maynes', 0, 345, 464),
    (3, 'francesc gelabert', 'adria maynes', 0, 387, 427),
    (4, 'joan sans', 'adria maynes', 0, 365, 498),
    (5, 'marta rovira', 'adria maynes', 1, 503, 449),
    (6, 'xavier albons', 'adria maynes', 1, 686, 370),
    (3, 'dani bardes', 'albert rodriguez', 0, 354, 454),
    (2, 'francesc gelabert', 'albert rodriguez', 0, 362, 500),
    (5, 'joan sans', 'albert rodriguez', 0, 337, 368),
    (4, 'marta rovira', 'albert rodriguez', 1, 519, 460),
    (7, 'xavier albons', 'albert rodriguez', 1, 505, 343),
    (1, 'francesc gelabert', 'dani bardes', 1, 433, 380),
    (6, 'joan sans', 'dani bardes', 1, 449, 375),
    (7, 'marta rovira', 'dani bardes', 1, 464, 422),
