INSERT INTO campionats (nom, data, temporada_codi, computa_barruf, finalitzat, rondes_jugades, ordre, origen, notes, primera_edicio)
VALUES ('Campionat de Cloenda Molins 2023-24', DATE '2024-07-06', '2023-24', TRUE, TRUE, 3, 172, 'arxiu AJUSC',
        'Importat de 2023-24/Barruf 172 - Campionat de Cloenda Molins 2023-24/Barruf 172 - Campionat de Cloenda Molins 2023-24.xlsx (comprovats). El motor reprodueix 8 dels 8 participants.', 172);

INSERT INTO inscripcions (campionat_id, jugador_id, victories)
SELECT c.id, n.jugador_id, i.v::numeric
FROM (VALUES ('marta rovira', NULL), ('isaac asensio', NULL), ('joan sans', NULL), ('albert rodriguez', NULL), ('francesc gelabert', NULL), ('xavier albons', NULL), ('albert rico', NULL), ('felipe calvo', NULL)) AS i(norm, v)
JOIN noms_arxiu n ON n.nom_norm = i.norm
CROSS JOIN (SELECT id FROM campionats WHERE primera_edicio = 172) c
ON CONFLICT DO NOTHING;

INSERT INTO partides (campionat_id, ronda, jugador_1_id, jugador_2_id, resultat_1, punts_1, punts_2)
SELECT c.id, p.ronda, n1.jugador_id, n2.jugador_id, p.resultat::numeric, p.p1::integer, p.p2::integer
FROM (VALUES
    (1, 'marta rovira', 'isaac asensio', 1, NULL, NULL),
    (1, 'joan sans', 'albert rodriguez', 1, NULL, NULL),
    (1, 'francesc gelabert', 'xavier albons', 1, NULL, NULL),
    (1, 'albert rico', 'felipe calvo', 1, NULL, NULL),
    (2, 'marta rovira', 'joan sans', 1, NULL, NULL),
    (2, 'francesc gelabert', 'albert rico', 1, NULL, NULL),
    (2, 'albert rodriguez', 'isaac asensio', 1, NULL, NULL),
    (2, 'felipe calvo', 'xavier albons', 1, NULL, NULL),
    (3, 'francesc gelabert', 'marta rovira', 1, NULL, NULL),
    (3, 'joan sans', 'felipe calvo', 0, NULL, NULL),
    (3, 'xavier albons', 'albert rodriguez', 0, NULL, NULL),
    (3, 'albert rico', 'isaac asensio', 1, NULL, NULL)
) AS p(ronda, j1, j2, resultat, p1, p2)
JOIN noms_arxiu n1 ON n1.nom_norm = p.j1
LEFT JOIN noms_arxiu n2 ON n2.nom_norm = p.j2
CROSS JOIN (SELECT id FROM campionats WHERE primera_edicio = 172) c;

INSERT INTO barruf_variacions (campionat_id, jugador_id, barruf_abans, partides, victories, esperanca, factor_k, variacio, barruf_despres)
