INSERT INTO inscripcions (campionat_id, jugador_id, victories)
SELECT c.id, n.jugador_id, i.v::numeric
FROM (VALUES ('vicenc castello', NULL), ('merce gabardos', NULL), ('anna bover', NULL), ('jordi plana espanol', NULL), ('francesca cama', NULL), ('conxita marin', NULL), ('eulalia guasch', NULL)) AS i(norm, v)
JOIN noms_arxiu n ON n.nom_norm = i.norm
CROSS JOIN (SELECT id FROM campionats WHERE primera_edicio = 178) c
ON CONFLICT DO NOTHING;

