-- =============================================================================
-- Edició 186: Lliga de Scrabble de Porreres 2025  (20/20 participants quadren amb el full)
-- =============================================================================
INSERT INTO campionats (nom, data, temporada_codi, computa_barruf, finalitzat, rondes_jugades, ordre, origen, notes, primera_edicio)
VALUES ('Lliga de Scrabble de Porreres 2025', DATE '2025-06-27', '2024-25', TRUE, TRUE, 18, 186, 'arxiu AJUSC',
        'Importat de 2024-25/Barruf 186 - Lliga de Scrabble de Porreres 2025/Barruf 186 - Lliga de Scrabble de Porreres 2025.xlsx (originals). El motor reprodueix 20 dels 20 participants.', 186);

INSERT INTO inscripcions (campionat_id, jugador_id, victories)
SELECT c.id, n.jugador_id, i.v::numeric
FROM (VALUES ('miquel gomila', NULL), ('joana mora', NULL), ('antoni manuel gorrias', NULL), ('francesca font', NULL), ('barbara mora', NULL), ('antonia riera', NULL), ('elisenda farre', NULL), ('joana a. matas', NULL), ('beatriu defior', NULL), ('pia ona verger', NULL), ('joan melia', NULL), ('francisca obrador', NULL), ('joana a. roig', NULL), ('caterina sureda vallespir', NULL), ('monica bisbal sitjar', NULL), ('maria sampol', NULL), ('antonia nicolau', NULL), ('catalina oliver', NULL), ('francisca nicolau', NULL), ('merce oliver', NULL)) AS i(norm, v)
JOIN noms_arxiu n ON n.nom_norm = i.norm
