INSERT INTO inscripcions (campionat_id, jugador_id, victories)
SELECT c.id, n.jugador_id, i.v::numeric
FROM (VALUES ('francesc gelabert', NULL), ('vicenc castello', NULL), ('adria maynes', NULL), ('manuel granados', NULL), ('marga gene', NULL), ('guillem casacuberta', NULL), ('xavier albons', NULL), ('anna rodrigo', NULL), ('joan puigmalet', NULL)) AS i(norm, v)
JOIN noms_arxiu n ON n.nom_norm = i.norm
CROSS JOIN (SELECT id FROM campionats WHERE primera_edicio = 190) c
ON CONFLICT DO NOTHING;

